from httpbin.core import app

client = app.test_client()

def test_basic_auth_empty_authorization_header_returns_401():
    r = client.get(
        '/basic-auth/u/p',
        headers={'Authorization': ''}
    )
    assert r.status_code == 401
    assert r.status_code != 200

test_basic_auth_empty_authorization_header_returns_401()

import base64
from httpbin.core import app

client = app.test_client()

def test_basic_auth_response_payload_exact_fields():
    creds = base64.b64encode(b'alice:secret').decode('ascii')
    r = client.get(
        '/basic-auth/alice/secret',
        headers={'Authorization': f'Basic {creds}'}
    )
    assert r.status_code == 200
    data = r.get_json()
    assert data == {'authenticated': True, 'user': 'alice'}

test_basic_auth_response_payload_exact_fields()
